// tools/sig/job/post.ts
var POST_NAMES = ["intro", "buy", "join", "how", "board", "open"];
var BOARD_ROWS = 10;
var POST_SIZES = { intro: [600, 288], buy: [296, 112], join: [296, 112], how: [600, 752], board: [600, 620], open: [600, 88] };
var num = (n) => n.toLocaleString("en-US");
var money = (n) => "$" + num(Math.round(n));
var tct = (at) => new Date(at * 1e3).toISOString().slice(11, 16);
var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
var when = (at, nowS) => {
  if (Math.floor(at / 86400) === Math.floor(nowS / 86400)) return tct(at);
  const d = new Date(at * 1e3);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`;
};
var esc = (s) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
var MARK = `<svg width="36" height="36" viewBox="0 0 28 28"><circle cx="14" cy="14" r="12.7" fill="none" stroke="#d94a3d" stroke-width="2.6"/><circle cx="14" cy="14" r="7.2" fill="none" stroke="#d94a3d" stroke-width="2.6"/><circle cx="14" cy="14" r="3.4" fill="#d94a3d"/></svg>`;
var arrow = (stroke) => `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="${stroke}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" style="flex:none"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`;
var CSS = `
:root{--panel:#141415;--raise:#1f1f22;--line2:#323235;--line3:#3f3f43;--edge:#2a2a2d;--ink:#ececec;--mute:#a1a1a6;--faint:#77777c;--green:#7cc96f;--on-green:#0b1309}
*{box-sizing:border-box}html,body{margin:0;background:transparent}body{padding:8px;display:flex;flex-direction:column;align-items:flex-start;gap:8px}
.img{position:relative;width:600px;background:var(--panel);border:1px solid var(--edge);border-radius:14px;overflow:hidden;font-family:Manrope,sans-serif;color:var(--ink);font-variant-numeric:tabular-nums}
.cap{font:700 15px/1 Manrope;letter-spacing:.12em;text-transform:uppercase;color:var(--mute)}
.wm{display:inline-flex;flex-direction:column;line-height:.9;white-space:nowrap}
.wm i{font:800 13px/1 Manrope;font-style:normal;margin-bottom:3px}
.wm b{font-family:Archivo;font-weight:900;font-stretch:125%;font-size:28px;letter-spacing:.01em;color:transparent;-webkit-text-stroke:1.2px var(--ink)}
#intro{height:288px}
#intro .bar{height:72px;display:flex;align-items:center;gap:12px;padding:0 28px;border-bottom:1px solid var(--edge)}
#intro .bar .cap{margin-left:auto}
#intro .say{padding:28px 28px 0;font:800 28px/1.25 Manrope;letter-spacing:-.015em}
#intro .old{margin:24px 28px 28px;height:64px;border:1px solid var(--line3);border-radius:12px;background:var(--raise);display:flex;align-items:center;gap:12px;padding:0 22px;font:800 21px Manrope}
#intro .old span{margin-left:auto;color:var(--mute);font:700 17px Manrope}
.act{width:296px;height:112px;border-radius:14px;display:flex;flex-direction:column;justify-content:center;gap:10px;padding:0 22px;font-family:Manrope,sans-serif;border:1px solid var(--edge)}
.act .an{display:flex;align-items:center;gap:10px;font:800 25px/1 Manrope;letter-spacing:-.015em;white-space:nowrap}
.act .as{font:700 16px/1.3 Manrope}
#buy{background:var(--green);color:var(--on-green);border-color:var(--green)}#buy .as{color:rgba(11,19,9,.75)}
#join{background:var(--raise);color:var(--ink);border-color:var(--line3)}#join .as{color:var(--mute)}#join .as b{color:var(--green)}
#how{height:752px}
#how .top{padding:30px 28px 26px;border-bottom:1px solid var(--edge)}
#how .top h2{margin:0;font:800 30px/1.15 Manrope;letter-spacing:-.02em}
#how .three{margin-top:16px;display:flex;flex-direction:column;gap:6px}
#how .three span{font:700 21px/1.3 Manrope;color:var(--mute)}#how .three span b{color:var(--ink)}
#how .steps{padding:26px 28px 10px}
#how .step{display:grid;grid-template-columns:52px 1fr;column-gap:14px;padding:20px 0;border-top:1px solid #222225}
#how .steps .cap+.step{border-top:0;padding-top:18px}
#how .step .k{font-family:Archivo;font-weight:900;font-stretch:125%;font-size:38px;line-height:1;color:transparent;-webkit-text-stroke:1.3px var(--mute)}
#how .step b{display:block;font:800 25px/1.15 Manrope}
#how .step span{display:block;margin-top:8px;font:600 20px/1.45 Manrope;color:var(--mute)}
#board .hd{height:76px;display:flex;align-items:center;padding:0 28px;border-bottom:1px solid var(--edge)}
#board h3{margin:0;font:800 27px Manrope;letter-spacing:-.015em}
#board .wk{margin-left:auto;font:700 18px Manrope;color:var(--mute)}
#board table{width:calc(100% - 56px);margin:0 28px;border-collapse:collapse;table-layout:fixed}
#board th{height:46px;text-align:left;font:700 14px Manrope;letter-spacing:.1em;color:var(--faint);border-bottom:2px solid var(--line2);padding:0}
#board td{height:44px;padding:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;border-bottom:1px solid #222225;font-size:20px}
#board tr:last-child td{border-bottom:0}
#board .t{color:var(--mute);font-weight:600}#board .w{font-weight:700}#board .c{text-align:right;color:var(--mute);font-weight:600}#board .r{text-align:right;font-weight:700}
#board .list{height:486px}
#board .none{margin:0 28px;padding:24px 0;font:600 20px Manrope;color:var(--faint)}
#board .ft{margin:0 28px;height:56px;display:flex;align-items:center;justify-content:flex-end;border-top:1px solid var(--edge);font:600 16px Manrope;color:var(--faint)}
#open{height:88px;display:flex;align-items:center;gap:12px;padding:0 28px;background:var(--raise);border-color:var(--line3)}
#open b{font:800 24px Manrope}#open span{margin-left:auto;font:700 17px Manrope;color:var(--mute)}
`;
function postPage(s, t, nowS) {
  const rows = s.board.slice(0, BOARD_ROWS);
  const board = rows.length === 0 ? `<div class="none">None lately</div>` : `<table><colgroup><col style="width:84px"><col><col style="width:130px"><col style="width:130px"></colgroup><tr><th>WHEN</th><th>TARGET</th><th class="c">BOUNTIES</th><th class="r">REWARD</th></tr>` + rows.map((r) => `<tr><td class="t">${when(r.at, nowS)}</td><td class="w">${esc(r.target)}</td><td class="c">${num(r.n)}</td><td class="r">${money(r.reward)}</td></tr>`).join("") + `</table>`;
  return `<!DOCTYPE html><html><head><meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@125,900&family=Manrope:wght@500;600;700;800&display=block" rel="stylesheet">
<style>${CSS}</style></head><body>
<div class="img" id="intro">
  <div class="bar">${MARK}<span class="wm"><i>the</i><b>COMPANY</b></span><span class="cap">Bounties on Torn</span></div>
  <div class="say">I'm a returning player who has previously run a bounty business.</div>
  <div class="old">Here's my old thread<span>Open</span>${arrow("#a1a1a6")}</div>
</div>
<div class="act" id="buy"><span class="an">Buy bounties${arrow("currentColor")}</span><span class="as">Pay in Xanax \xB7 stay anonymous</span></div>
<div class="act" id="join"><span class="an">Become an associate</span><span class="as">Earn <b>${money(t.associateCut)}\u2013${money(t.associateCutAnon)}</b><br>a bounty</span></div>
<div class="img" id="how">
  <div class="top"><h2>Bounties on anyone,<br>placed by our people.</h2>
    <div class="three"><span>You stay <b>anonymous</b>.</span><span>You pay in <b>Xanax</b>.</span><span>You watch <b>every bounty land</b>.</span></div></div>
  <div class="steps"><div class="cap">How it works</div>
    <div class="step"><span class="k">1</span><div><b>Request</b><span>The target, how many, the reward.</span></div></div>
    <div class="step"><span class="k">2</span><div><b>Pay in Xanax</b><span>Follow the instructions shown on the payment page, and make sure to attach the message to your payment.</span></div></div>
    <div class="step"><span class="k">3</span><div><b>Watch them land</b><span>Your own dashboard shows you when the bounties were placed and claimed, and your target's activity the moment you've placed a bounty order.</span></div></div>
  </div>
</div>
<div class="img" id="board">
  <div class="hd"><h3>Latest bounties</h3><span class="wk">${num(s.placedWeek)} this week</span></div>
  <div class="list">${board}</div>
  <div class="ft">Times in TCT</div>
</div>
<div class="img" id="open"><b>Open the Company</b><span>No API key needed to order</span>${arrow("#ececec")}</div>
</body></html>`;
}
async function drawPost(chromium, s, t, nowS) {
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage({ deviceScaleFactor: 2, viewport: { width: 800, height: 3e3 } });
    await page.setContent(postPage(s, t, nowS), { waitUntil: "networkidle" });
    await page.evaluate(() => document.fonts.ready);
    const out = {};
    for (const name of POST_NAMES) {
      const png = await page.locator(`#${name}`).screenshot({ omitBackground: true });
      const v = new DataView(png.buffer, png.byteOffset, png.byteLength), [w, h] = POST_SIZES[name];
      if (v.getUint32(16) !== w * 2 || v.getUint32(20) !== h * 2) throw new Error(`post ${name}: ${v.getUint32(16) / 2}x${v.getUint32(20) / 2}, not ${w}x${h}`);
      out[name] = png;
    }
    return out;
  } finally {
    await browser.close();
  }
}

// tools/sig/job/main.ts
var site = (process.env.SITE ?? "").replace(/\/+$/, "");
var secret = process.env.SIG_JOB_SECRET ?? "";
if (!site || !secret) throw new Error("set SITE and SIG_JOB_SECRET");
var auth = { Authorization: `Bearer ${secret}` };
if (process.argv[2] === "post") await post();
else await sigs();
async function sigs() {
  const design = assets_hd_default.design ?? "";
  const res = await fetch(`${site}/sig/job/check?${new URLSearchParams({ design })}`, { method: "POST", headers: auth });
  if (!res.ok) throw new Error(`check: ${res.status} ${await res.text()}`);
  const { values, behind } = await res.json();
  console.log(`counts ${values.n} / ${values.week} / ${values.board}; behind: ${behind.join(", ") || "none"}`);
  for (const name of behind) {
    const gif = renderFrom(assets_hd_default.pieces, name, values);
    const q = new URLSearchParams({ n: String(values.n), week: String(values.week), board: String(values.board), design });
    const up = await fetch(`${site}/sig/job/${name}.gif?${q}`, { method: "PUT", headers: { ...auth, "Content-Type": "image/gif" }, body: gif });
    if (!up.ok) throw new Error(`${name}: ${up.status} ${await up.text()}`);
    console.log(`${name}: ${Math.round(gif.length / 1024)} KB uploaded`);
  }
}
async function post() {
  const [stats, terms] = await Promise.all(["/api/public/stats", "/api/public/terms"].map(async (p) => {
    const r = await fetch(site + p);
    if (!r.ok) throw new Error(`${p}: ${r.status}`);
    return r.json();
  }));
  const { chromium } = await import("playwright");
  const pics = await drawPost(chromium, stats, terms, Math.floor(Date.now() / 1e3));
  for (const [name, png] of Object.entries(pics)) {
    const up = await fetch(`${site}/post/job/${name}.png`, { method: "PUT", headers: { ...auth, "Content-Type": "image/png" }, body: png });
    if (!up.ok) throw new Error(`post ${name}: ${up.status} ${await up.text()}`);
    console.log(`post ${name}: ${Math.round(png.length / 1024)} KB, ${(await up.json()).changed ? "new" : "same"}`);
  }
}
